        website = incident.StatusPageComponent("website", name="Website")
        api = incident.StatusPageComponent("api", name="API")
        database = incident.StatusPageComponent("database", name="Database")
        # The structure is the page's layout: items appear in the order listed, each one either a
        # single component or a named group of components. Display settings are optional; one left
        # out keeps whatever the dashboard has.
        public_status_page_structure = incident.StatusPageStructure("public",
            status_page_id=public.id,
            display_uptime_mode="chart_and_percentage",
            items=[
                {
                    "component_id": website.id,
                },
                {
                    "group": {
                        "name": "Backend",
                        "description": "The services behind the website",
                        "components": [
                            {
                                "component_id": api.id,
                            },
                            {
                                "component_id": database.id,
                                "display_uptime": False,
                            },
                        ],
                    },
                },
            ])
